<?php
require '../db.php'; require_role(['Admin']);
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['set_role'])){check_csrf();$id=(int)$_POST['user_id'];$role=(int)$_POST['role_id'];if($id!==(int)$_SESSION['user_id']){$s=$conn->prepare('UPDATE users SET RoleID=? WHERE UserID=?');$s->bind_param('ii',$role,$id);$s->execute();if($role===3){$s=$conn->prepare("INSERT INTO restaurants(owner_user_id,name,cuisine) SELECT UserID,FullName,'Local favorites' FROM users WHERE UserID=? AND NOT EXISTS(SELECT 1 FROM restaurants WHERE owner_user_id=?)");$s->bind_param('ii',$id,$id);$s->execute();}flash('Role updated.');}header('Location: index.php');exit;}
$users=(int)$conn->query('SELECT COUNT(*) n FROM users')->fetch_assoc()['n'];$stores=(int)$conn->query('SELECT COUNT(*) n FROM restaurants')->fetch_assoc()['n'];$orders=(int)$conn->query('SELECT COUNT(*) n FROM orders')->fetch_assoc()['n'];$revenue=(float)$conn->query("SELECT COALESCE(SUM(total),0) n FROM orders WHERE status='Delivered'")->fetch_assoc()['n'];$summary=$conn->query('SELECT status,COUNT(*) total FROM orders GROUP BY status');$recent=$conn->query('SELECT o.id,o.status,o.total,o.created_at,r.name restaurant,u.UserName customer FROM orders o JOIN restaurants r ON r.id=o.restaurant_id JOIN users u ON u.UserID=o.customer_id ORDER BY o.created_at DESC LIMIT 12');$accounts=$conn->query('SELECT u.UserID,u.UserName,u.Email,r.RoleID,r.RoleName FROM users u JOIN roles r ON r.RoleID=u.RoleID ORDER BY u.UserID DESC LIMIT 100');$roles=$conn->query('SELECT RoleID,RoleName FROM roles')->fetch_all(MYSQLI_ASSOC);page_start('Admin analytics');$msg=take_flash();if($msg)echo '<p class="pill">'.h($msg).'</p>';?>
<section class="hero"><span class="pill">OPERATIONS</span><h1>Platform overview</h1><p>Order counts, delivered revenue, recent activity, and account roles.</p><a class="btn" href="../orders.php">Manage orders</a> <a class="btn secondary" href="../restaurant.php">Menu management</a></section>
<div class="grid"><div class="card"><p class="muted">Users</p><h2><?=$users?></h2></div><div class="card"><p class="muted">Restaurants</p><h2><?=$stores?></h2></div><div class="card"><p class="muted">Orders</p><h2><?=$orders?></h2></div><div class="card"><p class="muted">Delivered revenue</p><h2><?=number_format($revenue,0)?> ₫</h2></div></div>
<section class="card" style="margin-top:18px"><h2>Orders by status</h2><?php while($s=$summary->fetch_assoc()):?><span class="pill" style="margin:4px"><?=h($s['status'])?>: <?=$s['total']?></span><?php endwhile;?></section>
<section class="card" style="margin-top:18px"><div class="row"><h2>Recent orders</h2><a class="btn secondary" href="export.php">Export CSV</a></div><table><thead><tr><th>Order</th><th>Customer</th><th>Restaurant</th><th>Status</th><th>Total</th><th>Date</th></tr></thead><tbody><?php while($o=$recent->fetch_assoc()):?><tr><td>#<?=$o['id']?></td><td><?=h($o['customer'])?></td><td><?=h($o['restaurant'])?></td><td><?=h($o['status'])?></td><td><?=number_format($o['total'],0)?> ₫</td><td><?=h($o['created_at'])?></td></tr><?php endwhile;?></tbody></table></section>
<section class="card" style="margin-top:18px"><h2>Users and roles</h2><table><thead><tr><th>Account</th><th>Email</th><th>Current role</th><th>Change role</th></tr></thead><tbody><?php while($u=$accounts->fetch_assoc()):?><tr><td><?=h($u['UserName'])?></td><td><?=h($u['Email'])?></td><td><?=h($u['RoleName'])?></td><td><?php if((int)$u['UserID']!==(int)$_SESSION['user_id']):?><form method="post" style="display:flex;gap:6px"><?php csrf_field();?><input type="hidden" name="user_id" value="<?=$u['UserID']?>"><select name="role_id" class="field" style="margin:0"><?php foreach($roles as $r):?><option value="<?=$r['RoleID']?>" <?=$r['RoleID']==$u['RoleID']?'selected':''?>><?=h($r['RoleName'])?></option><?php endforeach;?></select><button name="set_role">Save</button></form><?php else:?>Your admin account<?php endif;?></td></tr><?php endwhile;?></tbody></table></section><?php page_end();
